import json
import re
from datetime import date

_DAY_PATTERN = re.compile(r'^(\d{4})-(\d{2})-(\d{2})$')


def _parse_day(row):
    day = row['day']
    if not isinstance(day, str):
        raise ValueError('day must be a YYYY-MM-DD string')
    match = _DAY_PATTERN.match(day)
    if not match:
        raise ValueError(f'invalid day: {day!r}')
    try:
        return date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        raise ValueError(f'invalid day: {day!r}') from None


def _validate_row(row):
    if not isinstance(row, dict):
        raise ValueError(f'row must be an object: {row!r}')
    tenant = row.get('tenant')
    if not isinstance(tenant, str) or not tenant:
        raise ValueError('tenant must be a nonempty string')
    amount = row.get('amount_cents')
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise ValueError('amount_cents must be an integer')
    return amount, _parse_day(row)


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        rows = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError(f'malformed JSON: {exc}') from None
    if not isinstance(rows, list):
        raise ValueError('input must be a JSON array of rows')
    total_cents = 0
    first_day = None
    last_day = None
    for row in rows:
        amount, day = _validate_row(row)
        total_cents += amount
        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day
    return {
        'row_count': len(rows),
        'total_cents': total_cents,
        'first_day': first_day.isoformat() if first_day else None,
        'last_day': last_day.isoformat() if last_day else None,
    }"}

